```cpp
#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T; // 测试组数
    cin >> T;
    while(T--){
        int n; 
        cin >> n;
        vector<int> a(n);
        for(int i = 0; i < n; i++){
            cin >> a[i];
        }

        // dp[x] 表示子序列 [1,2,...,x] 的个数
        vector<long long> dp(n+1, 0LL);

        for(int i = 0; i < n; i++){
            int v = a[i];
            if(v == 1){
                // 可以新开一个子序列，只含 "1"
                dp[1] = (dp[1] + 1) % MOD;
            } else {
                // 扩展之前的 [1,2,...,v-1] 子序列
                // 注意这里 v > 1
                dp[v] = (dp[v] + dp[v-1]) % MOD;
            }
        }

        // 计算权值总和
        long long ans = 0;
        for(int x = 1; x <= n; x++){
            ans = (ans + x * dp[x]) % MOD;
        }

        cout << ans << "\n";
    }

    return 0;
}

```
